def is_power_of_two(x):
    return x > 0 and (x & (x - 1) == 0)

print("Checking for k=1 to k=15:")
for k in range(1, 16):
    target = 5**k + 3
    if is_power_of_two(target):
        # If it is a power of two, find n (log2(target))
        import math
        n = round(math.log2(target))
        print(f"k={k}: 5^{k} + 3 = {target}. Is a power of 2. n = {n}")
    else:
        print(f"k={k}: 5^{k} + 3 = {target}. Not a power of 2.")
